             (Z_to_bv 64 (p_abeg SB c i + rz_size n - 16)) (Z_to_bv 64 0x100000)
             s7 s8 s9 s10 s11 t3' t4' t5' t6') F (Z_to_bv 64 qenq_entry) fc None m4 (seg_rom asegs)).
